/* Name comparison (doc/spec_FS2.md §6), shared by libfnd and the fs
 * service; the libfnd functions of the API spec §11.7 are in name_api.c.
 * casefold_table.h is generated by foundation/lib/fnd/gen_casefold.py from
 * the same C+F table as tools/fs2, so the fs service, libfnd and the host
 * tool fold names alike. */
#include "name.h"

#include "casefold_table.h"

fnd_status fnd_utf8_next(const uint8_t *s, uint32_t len, uint32_t *pos, uint32_t *cp) {
    uint32_t i = *pos;
    if (i >= len)
        return FND_END;
    uint32_t c = s[i];
    uint32_t need, min;
    if (c < 0x80) {
        *cp = c;
        *pos = i + 1;
        return FND_OK;
    } else if ((c & 0xE0) == 0xC0) {
        need = 1, min = 0x80, c &= 0x1F;
    } else if ((c & 0xF0) == 0xE0) {
        need = 2, min = 0x800, c &= 0x0F;
    } else if ((c & 0xF8) == 0xF0) {
        need = 3, min = 0x10000, c &= 0x07;
    } else {
        return FND_E_BAD_PATH;
    }
    if (len - i - 1 < need)
        return FND_E_BAD_PATH;
    for (uint32_t k = 1; k <= need; ++k) {
        uint32_t b = s[i + k];
        if ((b & 0xC0) != 0x80)
            return FND_E_BAD_PATH;
        c = (c << 6) | (b & 0x3F);
    }
    if (c < min || c > 0x10FFFF || (c >= 0xD800 && c <= 0xDFFF))
        return FND_E_BAD_PATH;
    *cp = c;
    *pos = i + 1 + need;
    return FND_OK;
}

uint32_t fnd_casefold(uint32_t cp, uint32_t out[3]) {
    if (cp < 0x80u) { /* only A-Z fold in ASCII; skip the table search */
        out[0] = cp >= 'A' && cp <= 'Z' ? cp + 0x20u : cp;
        return 1;
    }
    uint32_t lo = 0, hi = FND_CASEFOLD_COUNT;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        uint32_t from = fnd_cf_from[mid];
        if (from == cp) {
            uint32_t to = fnd_cf_to[mid];
            if (!(to & 0x80000000u)) {
                out[0] = to;
                return 1;
            }
            const uint32_t *m = &fnd_cf_multi[(to & 0xFFFFu) * 3u];
            uint32_t n = 0;
            while (n < 3 && m[n])
                out[n] = m[n], ++n;
            return n;
        }
        if (from < cp)
            lo = mid + 1;
        else
            hi = mid;
    }
    out[0] = cp;
    return 1;
}

int fnd_fold_next(fnd_fold_iter *it, uint32_t *cp) {
    if (it->i == it->n) {
        if (it->pos < it->len && it->s[it->pos] < 0x80u) { /* ASCII fast path */
            uint32_t c = it->s[it->pos++];
            *cp = c >= 'A' && c <= 'Z' ? c + 0x20u : c;
            return 1;
        }
        uint32_t c;
        if (fnd_utf8_next(it->s, it->len, &it->pos, &c) != FND_OK)
            return 0;
        it->n = fnd_casefold(c, it->buf);
        it->i = 0;
    }
    *cp = it->buf[it->i++];
    return 1;
}

void fnd_fold_init(fnd_fold_iter *it, const uint8_t *s, uint32_t len) {
    it->s = s, it->len = len, it->pos = 0, it->n = 0, it->i = 0;
}

int fnd_name_key_equal(const uint8_t *a, uint32_t alen, const uint8_t *b, uint32_t blen) {
    fnd_fold_iter x, y;
    fnd_fold_init(&x, a, alen);
    fnd_fold_init(&y, b, blen);
    for (;;) {
        uint32_t ca, cb;
        int ha = fnd_fold_next(&x, &ca), hb = fnd_fold_next(&y, &cb);
        if (ha != hb)
            return 0;
        if (!ha)
            return 1;
        if (ca != cb)
            return 0;
    }
}

uint32_t fnd_name_key_hash(const uint8_t *s, uint32_t len) {
    fnd_fold_iter it;
    uint32_t h = 2166136261u, c;
    fnd_fold_init(&it, s, len);
    while (fnd_fold_next(&it, &c))
        h = (h ^ c) * 16777619u;
    return h;
}

fnd_status fnd_name_check(const uint8_t *s, uint32_t len, uint32_t *chars) {
    uint32_t pos = 0, n = 0, c;
    fnd_status st;
    if (len == 0)
        return FND_E_BAD_PATH;
    while ((st = fnd_utf8_next(s, len, &pos, &c)) == FND_OK) {
        if (c == '/' || c < 0x20 || (c >= 0x7F && c <= 0x9F))
            return FND_E_BAD_PATH;
        ++n;
    }
    if (st != FND_END)
        return FND_E_BAD_PATH;
    if ((len == 1 && s[0] == '.') || (len == 2 && s[0] == '.' && s[1] == '.'))
        return FND_E_BAD_PATH;
    if (n > 256 || len > 1024)
        return FND_E_NAME_TOO_LONG;
    *chars = n;
    return FND_OK;
}

